module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray, asString)
import std/string (split)
import std/list (length, map)

type Config = { appName: string, version: string, port: int, features: [string] }

func validate(name: string, version: string, port: int, features: [string]) -> Result[Config, string] =
  if port < 1024 || port > 65535 then Err("port out of range: ${show(port)}")
  else if length(split(version, ".")) != 3 then Err("invalid version format: ${version}")
  else if length(features) == 0 then Err("features list is empty")
  else Ok({ appName: name, version: version, port: port, features: features })

func parseConfig(content: string) -> Result[Config, string] =
  match decode(content) {
    Err(e) => Err("parse error: ${e}"),
    Ok(obj) => match (getString(obj, "app_name"), getString(obj, "version"), getInt(obj, "port"), getArray(obj, "features")) {
      (Some(name), Some(version), Some(port), Some(fs)) =>
        validate(name, version, port, map(\j. match asString(j) { Some(s) => s, None => "" }, fs)),
      _ => Err("missing or invalid field")
    }
  }

func loadConfig(path: string) -> Result[Config, string] ! {FS} =
  parseConfig(readFile(path))

export func main() -> () ! {IO, FS} {
  writeFile("app_config.json", "{\"app_name\": \"MyApp\", \"version\": \"1.0.0\", \"port\": 8080, \"features\": [\"logging\", \"auth\", \"api\"]}");
  match loadConfig("app_config.json") {
    Ok(c) => println("Loaded ${c.appName} v${c.version} on port ${show(c.port)} with ${show(length(c.features))} features"),
    Err(msg) => println("Error: ${msg}")
  }
}

